// Add a default photo instance into each card component's Photo frame so we can swap later
async function bake(cardId, photoId, w, h){
  const card = await figma.getNodeByIdAsync(cardId);
  const photoFrame = card.findOne(n=>n.name==="Photo");
  photoFrame.clipsContent=true;
  const pc = await figma.getNodeByIdAsync(photoId);
  const pi = pc.createInstance();
  photoFrame.appendChild(pi);
  pi.resize(w,h);
  pi.x=0; pi.y=0;
  // center-crop: keep aspect by scaling to cover
  return card.name+" photo="+pi.name+" "+Math.round(pi.width)+"x"+Math.round(pi.height);
}
