function cover(pi, fw, fh, sw, sh){
  const s = Math.max(fw/sw, fh/sh);
  pi.resize(sw*s, sh*s);
  pi.x = (fw - sw*s)/2;
  pi.y = (fh - sh*s)/2;
}
