for(const [cardId, fw, fh] of [["56:36",180,110],["56:55",60,60],["56:66",164,96]]){
  const card = await figma.getNodeByIdAsync(cardId);
  const pf = card.findOne(n=>n.name==="Photo");
  const pi = pf.children[0];
  cover(pi, fw, fh, 240, 160);
  out.push(card.name+": "+Math.round(pi.width)+"x"+Math.round(pi.height)+" @"+Math.round(pi.x)+","+Math.round(pi.y));
}
return out.join("\n");

