try{
const f = await figma.getNodeByIdAsync("98:317");
const rr = await figma.getNodeByIdAsync("56:88");
await figma.loadFontAsync({family:"Lato",style:"Bold"});
await figma.loadFontAsync({family:"Lato",style:"Regular"});
const rounds=[
  {name:"Round_JumpingJacks", title:"Jumping Jacks", time:"00:30", hash:"1513f5d7086ed9d38c1db245cf1cfa3441ddb093"},
  {name:"Round_Squats", title:"Squats", time:"01:00", hash:"a1b2c3d4e5f60718293a4b5c6d7e8f9012345678"},
  {name:"Round_BackwardLunge", title:"Backward Lunge", time:"00:30", hash:"f3c2b3c833d85a979d84e29240d775aaf3340834"},
];
let y=464;
const ids=[];
for(const d of rounds){
  const c=rr.createInstance();
  c.name=d.name;
  f.appendChild(c);
  c.x=20; c.y=y;
  c.findOne(n=>n.name==="Img").fills=[{type:"IMAGE",imageHash:d.hash,scaleMode:"FILL"}];
  const texts=c.findAll(n=>n.type==="TEXT");
  for(const t of texts){ if(t.name==="Title")t.characters=d.title; else if(t.name==="Time")t.characters=d.time; }
  ids.push(c.id+" "+d.name+" y="+y);
  y+=Math.round(c.height)+8;
}
return ids.join("\n")+" | end y="+y;
}catch(e){return "ERR: "+e.message;}

const ids=["5:6","5:14","5:2"]; // Jumping Jacks, Squats, Backward Lunge
const out=[];
for(const id of ids){
  const n=await figma.getNodeByIdAsync(id);
  let hash=null;
  const walk=(node)=>{ if(hash)return; if("fills" in node){ try{ const f=node.fills; if(f!==figma.mixed) for(const fill of f) if(fill.type==="IMAGE"){hash=fill.imageHash;return;} }catch(e){} } if("children" in node) for(const c of node.children) walk(c); };
  walk(n);
  out.push(n.name+"|"+id+"|"+hash);
}
return out.join("\n");

const jobs=[
  ["102:342","0e6eb7eb4debf109865ea677116bb2e31153a74c"], // Jumping Jacks
  ["102:351","6b3c80354a3fbe4f8d862855c80693ad74dea497"], // Squats
];
