  c.findOne(n=>n.name==="Img").fills=[{type:"IMAGE",imageHash:hash,scaleMode:"FILL"}];
}
// audit all IMG fills in Home and Explore
const out=["rounds fixed"];
for(const fid of ["63:41","76:187"]){
  const f = await figma.getNodeByIdAsync(fid);
  const walk=(node)=>{
    if("fills" in node){ try{ const fl=node.fills; if(fl!==figma.mixed) for(const fill of fl) if(fill.type==="IMAGE") out.push(f.name+"/"+node.parent.name+"/"+node.name+" "+fill.imageHash.slice(0,10)); }catch(e){} }
    if("children" in node) for(const c of node.children) walk(c);
  };
  walk(f);
}
return out.join("\n");

